            ++i;
            ((PathAttachmentSample *)((char *)primary_samples + sample_offset))
                ->transform.position.y = -((1.0f - Cos(angle)) * curve_source);
            float z = (float)i;
            ((PathAttachmentSample *)((char *)primary_samples + sample_offset))
                ->transform.position.z = z;
            ((PathAttachmentSample *)((char *)secondary_samples + sample_offset))
