                        facequads[face_offset].vertex_2 =
                            column +
                            (row + 1) * ((unsigned short)path->width_cells + 1);
                        facequads[face_offset].vertex_3 =
                            (row + 1) * ((unsigned short)path->width_cells + 1) +
                            column + 1;
                        if (((column ^ row) & 1) == 0)
                            facequads[face_offset].texture_ref =
                                g_texture_refs.Add(texture_b, 0, 0);
                        else
                            facequads[face_offset].texture_ref =
                                g_texture_refs.Add(texture_b, 0, 0);
                    }
                    if (face_index == 0)
                    {
                        facequads[face_offset].uv[0].u = u0;
                        facequads[face_offset].uv[0].v = v0;
                        facequads[face_offset].uv[1].u = u1;
                        facequads[face_offset].uv[1].v = v0;
                        facequads[face_offset].uv[2].u = u1;
                        facequads[face_offset].uv[2].v = v1;
                        facequads[face_offset].uv[3].u = u0;
                        facequads[face_offset].uv[3].v = v1;
                    }
                    else
                    {
                        facequads[face_offset].uv[0].u = u1;
                        facequads[face_offset].uv[0].v = v0;
                        facequads[face_offset].uv[1].u = u0;
                        facequads[face_offset].uv[1].v = v0;
                        facequads[face_offset].uv[2].u = u0;
                        facequads[face_offset].uv[2].v = v1;
                        facequads[face_offset].uv[3].u = u1;
                        facequads[face_offset].uv[3].v = v1;
                    }
                }
                ++column;
            } while (column < path->width_cells);
        }
    }
}

void cRPath::PATH_FUNCTION(PATH_SIGNATURE)
{
#if PATH_VARIANT == 5
    float curve_count_source = curve_source * 5.0f;
    int curve_count;
#else
    int curve_count = PATH_CURVE_COUNT;
#endif
    float height_scale_value = PATH_HEIGHT_SCALE;
#if PATH_VARIANT != 5
    int i;
#endif

#if PATH_VARIANT == 5
    kind = PATH_TEMPLATE_KIND_DIP;
#endif
    is_mirrored_x = 0;
    side_exit_mode = 0;
    width_cells = width_cells_;
#if PATH_VARIANT != 5
    width_or_scale = 1.0f;
#endif

#if PATH_VARIANT == 0 || PATH_VARIANT == 1
    float loop_wiggle = 0.0f;
    kind = PATH_TEMPLATE_KIND_LOOPTHELOOP_FAMILY;
    if (width_cells_ == 4)
    {
#if PATH_VARIANT == 1
        kind = PATH_TEMPLATE_KIND_LOOPTHELOOPW;
#else
        kind = PATH_TEMPLATE_KIND_LOOPTHELOOP_FAMILY;
#endif
        loop_wiggle = 0.30000001f;
    }
    segment_count = curve_count + 14;
    segment_count_f = (float)(curve_count + 14);
    float curve_count_f = (float)curve_count;
    float loop_radius = curve_count_f * 0.15915494f;
    GetNodes();
    has_entry_mesh_transition = 1;

    for (i = 0; i < 7; ++i)
    {
        float z = (float)i;
        float center = (float)width_cells * 0.5f - 4.0f - z * 0.14285715f * loop_wiggle;
        initialize_sample_pair(&primary_samples[i], &secondary_samples[i], center, 0.0f,
                               0.49000001f, z, 1);
    }

    for (i = 0; i < 7; ++i)
    {
        int sample_index = curve_count + 7 + i;
        float z = (float)(i + 7);
        float center = (1.0f - (float)i * 0.16666667f) * loop_wiggle + 4.0f -
                       (float)width_cells * 0.5f;
        initialize_sample_pair(&primary_samples[sample_index],
                               &secondary_samples[sample_index], center, 0.0f,
                               0.49000001f, z, 1);
    }

    if (curve_count > 0)
    {
        float secondary_radius = loop_radius - 0.49000001f;
        for (i = 0; i < curve_count; ++i)
        {
            int sample_index = i + 7;
            float sample_f = (float)i;
            float angle = sample_f * 6.2831855f / curve_count_f;
            float center = (primary_samples[curve_count + 7].center_x -
                            primary_samples[0].center_x) *
                               sample_f / curve_count_f +
                           primary_samples[0].center_x;
            center += Sin(angle * 0.5f + 4.712389f) * loop_wiggle;

            primary_samples[sample_index].center_x = center;
            primary_samples[sample_index].rotation_scalar_98 = 0.0f;
            primary_samples[sample_index].rotation_scalar_94 = 0.0f;
            primary_samples[sample_index].special_scalar = 0.0f;
            primary_samples[sample_index].lateral_scale = 1.0f;
            primary_samples[sample_index].transform.Identity();
            primary_samples[sample_index].transform.position.x =
                primary_samples[sample_index].center_x;
            primary_samples[sample_index].transform.position.z =
                Sin(angle) * loop_radius + 7.0f;
            primary_samples[sample_index].transform.position.y =
                loop_radius - Cos(angle) * loop_radius;

            secondary_samples[sample_index].transform.Identity();
            secondary_samples[sample_index].transform.position.x =
                primary_samples[sample_index].center_x;
            secondary_samples[sample_index].transform.position.z =
                Sin(angle) * secondary_radius + 7.0f;
            secondary_samples[sample_index].transform.position.y =
                loop_radius - Cos(angle) * secondary_radius;

            orient_loop_sample(
                &primary_samples[sample_index],
                loop_radius - primary_samples[sample_index].transform.position.y,
                7.0f - primary_samples[sample_index].transform.position.z);
            orient_loop_sample(
                &secondary_samples[sample_index],
                loop_radius - secondary_samples[sample_index].transform.position.y,
                7.0f - secondary_samples[sample_index].transform.position.z);

#if PATH_VARIANT == 1
            float roll = Sin(angle * 0.5f) * Sin(angle * 8.0f) * 0.39269909f;
            primary_samples[sample_index].transform.RotLocalZ(roll);
            secondary_samples[sample_index].transform.RotLocalZ(roll);
#endif
        }
    }
#elif PATH_VARIANT == 2
    kind = PATH_TEMPLATE_KIND_LOOPOUT;
    segment_count = curve_count + 14;
    segment_count_f = (float)(curve_count + 14);
    float curve_count_f = (float)curve_count;
    float loop_radius = curve_count_f * 0.15915494f;
    GetNodes();
    has_entry_mesh_transition = 1;

    for (i = 0; i < 10; ++i)
    {
        float z = (float)i;
        float center = (float)width_cells * 0.5f - 4.0f - z * 0.11111111f * 0.30000001f;
        initialize_sample_pair(&primary_samples[i], &secondary_samples[i], center, 0.0f,
                               0.49000001f, z, 1);
    }

    for (i = 0; i < 4; ++i)
    {
        int sample_index = curve_count + 10 + i;
        float z = (float)(i + 10);
        float center = (1.0f - (float)i * 0.33333334f) * 0.30000001f + 4.0f -
                       (float)width_cells * 0.5f;
        initialize_sample_pair(&primary_samples[sample_index],
                               &secondary_samples[sample_index], center, 0.0f,
                               0.49000001f, z, 1);
    }

    if (curve_count > 0)
    {
        float center_y = -loop_radius;
        float secondary_radius = loop_radius + 0.49000001f;
        for (i = 0; i < curve_count; ++i)
        {
            int sample_index = i + 10;
            float sample_f = (float)i;
            float angle = sample_f * 6.2831855f / curve_count_f;
            float center = (primary_samples[curve_count + 10].center_x -
                            primary_samples[0].center_x) *
                               sample_f / curve_count_f +
                           primary_samples[0].center_x;
            center += Sin(angle * 0.5f + 4.712389f) * 0.30000001f;

            primary_samples[sample_index].center_x = center;
            primary_samples[sample_index].rotation_scalar_98 = 0.0f;
            primary_samples[sample_index].rotation_scalar_94 = 0.0f;
            primary_samples[sample_index].special_scalar = 0.0f;
            primary_samples[sample_index].lateral_scale = 1.0f;
            primary_samples[sample_index].transform.Identity();
            primary_samples[sample_index].transform.position.x =
                primary_samples[sample_index].center_x;
            primary_samples[sample_index].transform.position.z =
                Sin(angle) * loop_radius + 10.0f;
            primary_samples[sample_index].transform.position.y =
                Cos(angle) * loop_radius + center_y;

            secondary_samples[sample_index].transform.Identity();
            secondary_samples[sample_index].transform.position.x =
                primary_samples[sample_index].center_x;
            secondary_samples[sample_index].transform.position.z =
                Sin(angle) * secondary_radius + 10.0f;
            secondary_samples[sample_index].transform.position.y =
                Cos(angle) * secondary_radius + center_y;

            orient_loop_sample(
                &primary_samples[sample_index],
                primary_samples[sample_index].transform.position.y - center_y,
                primary_samples[sample_index].transform.position.z - 10.0f);
            orient_loop_sample(
                &secondary_samples[sample_index],
                secondary_samples[sample_index].transform.position.y - center_y,
                secondary_samples[sample_index].transform.position.z - 10.0f);
        }
    }
#elif PATH_VARIANT == 3 || PATH_VARIANT == 4
#if PATH_VARIANT == 3
    kind = PATH_TEMPLATE_KIND_FAMILY_10;
    float vertical_sign = 1.0f;
    float start_center = (float)width_cells * 0.5f - 4.0f;
    float end_center = 4.0f - (float)width_cells * 0.5f;
#else
    kind = PATH_TEMPLATE_KIND_FAMILY_11;
    float vertical_sign = -1.0f;
    float start_center = -(float)width_cells * 0.5f + 4.0f;
    float end_center = (float)width_cells * 0.5f - 4.0f;
#endif
    segment_count = curve_count + 14;
    segment_count_f = (float)(curve_count + 14);
    float curve_count_f = (float)curve_count;
    float hump_radius = curve_count_f * 0.095492966f;
    GetNodes();
    has_entry_mesh_transition = 0;

    for (i = 0; i < 7; ++i)
    {
        initialize_sample_pair(&primary_samples[i], &secondary_samples[i], start_center,
                               0.0f, 0.49000001f, (float)i, 0);
    }

    for (i = 0; i < 7; ++i)
    {
        int sample_index = curve_count + 7 + i;
        initialize_sample_pair(&primary_samples[sample_index],
                               &secondary_samples[sample_index], end_center, 0.0f,
                               0.49000001f, (float)(curve_count + 7 + i), 0);
    }

    if (curve_count > 0)
    {
        for (i = 0; i < curve_count; ++i)
        {
            int sample_index = i + 7;
            float angle = (float)i * 6.2831855f / curve_count_f;
            float y =
                vertical_sign * (1.0f - Cos(angle)) * hump_radius * height_scale_value;
            float center = Cos(angle * 0.5f) * start_center;
            initialize_sample_pair(&primary_samples[sample_index],
                                   &secondary_samples[sample_index], center, y,
                                   y + 0.49000001f, (float)(i + 7), 0);
            if (sample_index <= 7)
            {
                primary_samples[sample_index - 1].transform.RotIdentity();
                secondary_samples[sample_index - 1].transform.RotIdentity();
            }
            else
            {
                orient_previous_with_fixed_right(&primary_samples[sample_index - 1],
                                                 &primary_samples[sample_index]);
                orient_previous_with_fixed_right(&secondary_samples[sample_index - 1],
                                                 &secondary_samples[sample_index]);
            }
        }
    }
#elif PATH_VARIANT == 5
    curve_count = (int)curve_count_source;
    width_cells_ = curve_count;
    width_or_scale = height_scale_value;
    int endpoint_index = curve_count + 1;
    segment_count = endpoint_index + 1;
    segment_count_f = (float)(endpoint_index + 1);
    float curve_count_f = (float)curve_count;
    curve_source = curve_count_f * 0.047746483f;
    GetNodes();
    has_entry_mesh_transition = 0;

    primary_samples[0].center_x = 0.0f;
    primary_samples[0].rotation_scalar_98 = 0.0f;
    primary_samples[0].rotation_scalar_94 = 0.0f;
    primary_samples[0].special_scalar = 0.0f;
    primary_samples[0].lateral_scale = height_scale_value;
    primary_samples[0].transform.Identity();
    primary_samples[0].transform.position.x = primary_samples[0].center_x;
    primary_samples[0].transform.position.y = 0.0f;
    primary_samples[0].transform.position.z = 0.0f;
    secondary_samples[0].transform.Identity();
    secondary_samples[0].transform.position.x = primary_samples[0].center_x;
    secondary_samples[0].transform.position.y = 0.49000001f;
    secondary_samples[0].transform.position.z = 0.0f;

    int endpoint_sample_offset = endpoint_index * (int)sizeof(PathAttachmentSample);
    ((PathAttachmentSample *)((char *)primary_samples + endpoint_sample_offset))
        ->center_x = 0.0f;
    ((PathAttachmentSample *)((char *)primary_samples + endpoint_sample_offset))
        ->rotation_scalar_98 = 0.0f;
    ((PathAttachmentSample *)((char *)primary_samples + endpoint_sample_offset))
        ->rotation_scalar_94 = 0.0f;
    ((PathAttachmentSample *)((char *)primary_samples + endpoint_sample_offset))
        ->special_scalar = 0.0f;
    ((PathAttachmentSample *)((char *)primary_samples + endpoint_sample_offset))
        ->lateral_scale = height_scale_value;
    ((PathAttachmentSample *)((char *)primary_samples + endpoint_sample_offset))
        ->transform.Identity();
    ((PathAttachmentSample *)((char *)primary_samples + endpoint_sample_offset))
        ->transform.position.x =
        ((PathAttachmentSample *)((char *)primary_samples + endpoint_sample_offset))
            ->center_x;
    ((PathAttachmentSample *)((char *)primary_samples + endpoint_sample_offset))
        ->transform.position.y = 0.0f;
    float endpoint_z = (float)endpoint_index;
    ((PathAttachmentSample *)((char *)primary_samples + endpoint_sample_offset))
        ->transform.position.z = endpoint_z;
    ((PathAttachmentSample *)((char *)secondary_samples + endpoint_sample_offset))
        ->transform.Identity();
    ((PathAttachmentSample *)((char *)secondary_samples + endpoint_sample_offset))
        ->transform.position.x =
        ((PathAttachmentSample *)((char *)primary_samples + endpoint_sample_offset))
            ->center_x;
    ((PathAttachmentSample *)((char *)secondary_samples + endpoint_sample_offset))
        ->transform.position.y = 0.49000001f;
    ((PathAttachmentSample *)((char *)secondary_samples + endpoint_sample_offset))
        ->transform.position.z = endpoint_z;

    int curve_phase_index = 0;
    if (width_cells_ > 0)
    {
        int i = 0;
        int sample_offset = (int)sizeof(PathAttachmentSample);
        do
        {
            ((PathAttachmentSample *)((char *)primary_samples + sample_offset))
                ->center_x = 0.0f;
            ((PathAttachmentSample *)((char *)primary_samples + sample_offset))
                ->rotation_scalar_98 = 0.0f;
            ((PathAttachmentSample *)((char *)primary_samples + sample_offset))
                ->rotation_scalar_94 = 0.0f;
            ((PathAttachmentSample *)((char *)primary_samples + sample_offset))
                ->special_scalar = 0.0f;
            ((PathAttachmentSample *)((char *)primary_samples + sample_offset))
                ->lateral_scale = 1.0f;
            float angle = (float)curve_phase_index * 6.2831855f / curve_count_f;
            ((PathAttachmentSample *)((char *)primary_samples + sample_offset))
                ->transform.Identity();
            ((PathAttachmentSample *)((char *)primary_samples + sample_offset))
                ->transform.position.x =
                ((PathAttachmentSample *)((char *)primary_samples + sample_offset))
                    ->center_x;
            ++i;
            ((PathAttachmentSample *)((char *)primary_samples + sample_offset))
                ->transform.position.y = -((1.0f - Cos(angle)) * curve_source);
            float z = (float)i;
            ((PathAttachmentSample *)((char *)primary_samples + sample_offset))
                ->transform.position.z = z;
            ((PathAttachmentSample *)((char *)secondary_samples + sample_offset))
                ->transform.Identity();
            ((PathAttachmentSample *)((char *)secondary_samples + sample_offset))
                ->transform.position.x =
                ((PathAttachmentSample *)((char *)primary_samples + sample_offset))
                    ->center_x;
            ((PathAttachmentSample *)((char *)secondary_samples + sample_offset))
                ->transform.position.y =
                0.49000001f - (1.0f - Cos(angle)) * curve_source;
            ((PathAttachmentSample *)((char *)secondary_samples + sample_offset))
                ->transform.position.z = z;
            if (sample_offset > (int)sizeof(PathAttachmentSample))
            {
                ((PathAttachmentSample *)((char *)primary_samples + sample_offset))[-1].transform.basis_right = Vector3(1.0f, 0.0f, 0.0f);
                ((PathAttachmentSample *)((char *)primary_samples + sample_offset))[-1].transform.basis_forward = ((PathAttachmentSample *)((char *)primary_samples + sample_offset))->transform.position - ((PathAttachmentSample *)((char *)primary_samples + sample_offset))[-1].transform.position;
                ((PathAttachmentSample *)((char *)primary_samples + sample_offset))[-1].transform.basis_forward.Normalize();
                ((PathAttachmentSample *)((char *)primary_samples + sample_offset))[-1].transform.basis_up.Cross(((PathAttachmentSample *)((char *)primary_samples + sample_offset))[-1].transform.basis_forward, ((PathAttachmentSample *)((char *)primary_samples + sample_offset))[-1].transform.basis_right);
                ((PathAttachmentSample *)((char *)secondary_samples + sample_offset))[-1].transform.basis_right = Vector3(1.0f, 0.0f, 0.0f);
                ((PathAttachmentSample *)((char *)secondary_samples + sample_offset))[-1].transform.basis_forward = ((PathAttachmentSample *)((char *)secondary_samples + sample_offset))->transform.position - ((PathAttachmentSample *)((char *)secondary_samples + sample_offset))[-1].transform.position;
                ((PathAttachmentSample *)((char *)secondary_samples + sample_offset))[-1].transform.basis_forward.Normalize();
                ((PathAttachmentSample *)((char *)secondary_samples + sample_offset))[-1].transform.basis_up.Cross(((PathAttachmentSample *)((char *)secondary_samples + sample_offset))[-1].transform.basis_forward, ((PathAttachmentSample *)((char *)secondary_samples + sample_offset))[-1].transform.basis_right);
            }
            else
            {
                ((PathAttachmentSample *)((char *)primary_samples + sample_offset))[-1].transform.RotIdentity();
                ((PathAttachmentSample *)((char *)secondary_samples + sample_offset))[-1].transform.RotIdentity();
            }
            sample_offset += (int)sizeof(PathAttachmentSample);
            curve_phase_index = i;
        } while (i < width_cells_);
    }
#elif PATH_VARIANT == 6
    kind = PATH_TEMPLATE_KIND_SCREW;
    segment_count = curve_count + 8;
    segment_count_f = (float)(curve_count + 8);
    GetNodes();
    has_entry_mesh_transition = 0;

    for (i = 0; i < 3; ++i)
    {
        initialize_sample_pair(&primary_samples[i], &secondary_samples[i], 0.5f, 0.0f,
                               0.49000001f, (float)i, 0);
    }

    for (i = 0; i < 5; ++i)
    {
        int sample_index = curve_count + 3 + i;
        initialize_sample_pair(&primary_samples[sample_index],
                               &secondary_samples[sample_index], -0.5f, 0.0f,
                               0.49000001f, (float)(curve_count + 3 + i), 0);
    }

    if (curve_count > 0)
    {
        float curve_count_f = (float)curve_count;
        for (i = 0; i < curve_count; ++i)
        {
            int sample_index = i + 3;
            float angle = (float)i * 6.2831855f / curve_count_f;
            float center = Cos(angle * 0.5f) * 0.5f;
            initialize_sample_pair(&primary_samples[sample_index],
                                   &secondary_samples[sample_index], center, 0.0f,
                                   Cos(angle) * 0.49000001f, (float)(i + 3), 0);
            primary_samples[sample_index].rotation_scalar_94 = angle;
            secondary_samples[sample_index].transform.position.x =
                primary_samples[sample_index].center_x - Sin(angle) * 0.49000001f;
            if (sample_index <= 3)
            {
                primary_samples[sample_index - 1].transform.RotIdentity();
                secondary_samples[sample_index - 1].transform.RotIdentity();
            }
            else
            {
                float up_x = -Sin(angle);
                float up_y = Cos(angle);
                orient_previous_with_fixed_up(&primary_samples[sample_index - 1],
                                              &primary_samples[sample_index], up_x,
                                              up_y, 0.0f, 0.0f);
                orient_previous_with_fixed_up(&secondary_samples[sample_index - 1],
                                              &secondary_samples[sample_index], up_x,
                                              up_y, 0.0f, 0.0f);
            }
        }
    }
#elif PATH_VARIANT == 7
    kind = PATH_TEMPLATE_KIND_SLALOM;
    segment_count = curve_count + 8;
    segment_count_f = (float)(curve_count + 8);
    GetNodes();
    has_entry_mesh_transition = 0;

    for (i = 0; i < 4; ++i)
    {
        initialize_sample_pair(&primary_samples[i], &secondary_samples[i], 0.0f, 0.0f,
                               0.49000001f, (float)i, 0);
    }

    for (i = 0; i < 4; ++i)
    {
        int sample_index = curve_count + 4 + i;
        initialize_sample_pair(&primary_samples[sample_index],
                               &secondary_samples[sample_index], 0.0f, 0.0f,
                               0.49000001f, (float)(curve_count + 4 + i), 0);
    }

    if (curve_count > 0)
    {
        float curve_count_f = (float)curve_count;
        for (i = 0; i < curve_count; ++i)
        {
            int sample_index = i + 4;
            float t = (float)i / curve_count_f;
            float angle = t * 6.2831855f;
            float falloff = t - 0.5f;
            if (falloff < 0.0f)
                falloff = -falloff;
            float center = Sin(angle) * (1.0f - falloff) * (1.0f - falloff) * 5.0f;
            initialize_sample_pair(&primary_samples[sample_index],
                                   &secondary_samples[sample_index], center, 0.0f,
                                   0.49000001f, (float)(i + 4), 0);
            if (sample_index <= 4)
            {
                primary_samples[sample_index - 1].transform.RotIdentity();
                secondary_samples[sample_index - 1].transform.RotIdentity();
            }
            else
            {
                float roll = primary_samples[sample_index - 1].center_x * 0.2617994f;
                orient_previous_with_fixed_up(&primary_samples[sample_index - 1],
                                              &primary_samples[sample_index], 0.0f,
                                              1.0f, 0.0f, roll);
                orient_previous_with_fixed_up(&secondary_samples[sample_index - 1],
                                              &secondary_samples[sample_index], 0.0f,
                                              1.0f, 0.0f, roll);
            }
        }
    }
#endif

    if (segment_count - 1 > 0)
    {
        int delta_index = 0;
        int delta_sample_offset = 0;
        do
        {
            ((PathAttachmentSample *)((char *)primary_samples + delta_sample_offset))
                ->delta_dir_to_next =
                ((PathAttachmentSample *)((char *)primary_samples +
                                          delta_sample_offset) +
                 1)
                    ->transform.position -
                ((PathAttachmentSample *)((char *)primary_samples +
                                          delta_sample_offset))
                    ->transform.position;
            ((PathAttachmentSample *)((char *)primary_samples + delta_sample_offset))
                ->delta_length = ((PathAttachmentSample *)((char *)primary_samples +
                                                           delta_sample_offset))
                                     ->delta_dir_to_next.Normalize();

            ((PathAttachmentSample *)((char *)secondary_samples + delta_sample_offset))
                ->delta_dir_to_next =
                ((PathAttachmentSample *)((char *)secondary_samples +
                                          delta_sample_offset) +
                 1)
                    ->transform.position -
                ((PathAttachmentSample *)((char *)secondary_samples +
                                          delta_sample_offset))
                    ->transform.position;
            ((PathAttachmentSample *)((char *)secondary_samples + delta_sample_offset))
                ->delta_length = ((PathAttachmentSample *)((char *)secondary_samples +
                                                           delta_sample_offset))
                                     ->delta_dir_to_next.Normalize();

            ++delta_index;
            delta_sample_offset += (int)sizeof(PathAttachmentSample);
        } while (delta_index < segment_count - 1);
    }

    primary_samples[segment_count - 1].delta_dir_to_next = Vector3(0.0f, 0.0f, 1.0f);
    primary_samples[segment_count - 1].delta_length = 1.0f;
    secondary_samples[segment_count - 1].delta_dir_to_next = Vector3(0.0f, 0.0f, 1.0f);
    secondary_samples[segment_count - 1].delta_length = 1.0f;

    build_strip_mesh(this, texture_a, texture_b);

    CalcLengthZ();
    (void)side_exit;
